import express from 'express';
import multer from 'multer';

const app = express();

// Cartas: JSON (API) e formulário de página (urlencoded) — com LIMITES.
app.use(express.json({ limit: '100kb' }));
app.use(express.urlencoded({ extended: true }));

// Encomendas: multer guarda o upload na memória e libera em req.file.
const upload = multer({
  storage: multer.memoryStorage(), // conteúdo fica em req.file.buffer
  limits: { fileSize: 5 * 1024 * 1024 }, // 5 MB — regra da agência
});

app.post('/api/perfil', upload.single('avatar'), (req, res) => {
  // req.file existe quando o cliente mandou um arquivo no campo 'avatar'.
  res.json({
    nome: req.file?.originalname,
    tamanho: req.file?.size,
    campos: req.body, // os campos do formulário chegam juntos
  });
});

// Estourou o limite? O multer lança um erro com código LIMIT_FILE_SIZE.
app.use((erro, req, res, next) => {
  if (erro.code === 'LIMIT_FILE_SIZE') {
    return res.status(413).json({ erro: 'arquivo excede o limite' });
  }
  next(erro); // erro desconhecido segue para o tratamento central
});

import express from 'express';
import multer from 'multer';

const app = express();
app.use(express.json({ limit: '100kb' }));

// 1. Encomenda: multer recebe o multipart e entrega o arquivo em req.file.
const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 }, // 5 MB
});

app.post('/api/perfil', upload.single('avatar'), (req, res) => {
  // 2. Sem arquivo no campo 'avatar', req.file é undefined — recusamos.
  if (!req.file) {
    return res.status(400).json({ erro: 'arquivo avatar é obrigatório' });
  }
  // 3. Chegou: devolvemos o nome e o tamanho. O conteúdo vive em req.file.buffer.
  res.status(201).json({
    nome: req.file.originalname,
    tamanho: req.file.size,
    camposDoFormulario: req.body,
  });
});

// 4. Erros do multer caem aqui como QUALQUER outro erro da cadeia.
app.use((erro, req, res, next) => {
  // 5. Arquivo grande demais é problema do CLIENTE → 413 (Payload Too Large).
  if (erro.code === 'LIMIT_FILE_SIZE') {
    return res.status(413).json({ erro: 'arquivo excede o limite de 5MB' });
  }
  // 6. Qualquer outra coisa é erro interno do servidor.
  res.status(500).json({ erro: 'erro interno do servidor' });
});

app.listen(3000);

